import { breakpoints } from '../foundation/gridSystem';

// `tablet` mirrors the confirmed foundation token `breakpoints.md` — imported rather than
// retyped so the two cannot drift apart. `tabletWide` and `desktop` have no foundation
// equivalent yet; `desktop` additionally conflicts with Chakra's lg (62em) and xl (80em),
// which is why every desktop rule below is a raw @media rather than a responsive prop.
//
// theme/components/ otherwise avoids direct foundation/ imports in favour of --zimm-* CSS
// vars. Breakpoints are a deliberate exception: media queries cannot consume var().
// px ÷ 16; WCAG 1.4.4 requires em so queries shift with browser zoom.
const BP = {
  tablet: breakpoints.md, // Figma: alias/breakpoint/tablet — 768px
  tabletWide: '53.75em', // Figma: alias/breakpoint/tablet-wide — 860px (no foundation equivalent)
  desktop: '64em', // Figma: alias/breakpoint/desktop — 1024px (≠ Chakra lg=62em / xl=80em)
} as const;

// Provisional spacing/size values — kept here as named references until the UI designer
// confirms the token in foundation/spacing.ts or foundation/sizes.ts.
//
// SPACE_SECTION and SIZE_COL_NAV are NOT missing tokens: --zimm-scale-1200 (48px) and
// --zimm-scale-3500 (140px) already carry the same values. They are deliberately kept as
// rem here because those two foundation aliases are px, which does not scale under browser
// zoom (WCAG 1.4.4 — see overrideStyling.md Units). Collapse them onto the vars only once
// the foundation aliases move to rem.
const SPACE_SECTION = '3rem'; // alias/space/section (48px)
const SIZE_COL_NAV = '8.75rem'; // alias/size/footer/col-width-nav (140px)
const SIZE_COL_SUB = '20rem'; // alias/size/footer/col-width-subscribe (320px)
const SIZE_COL_MAP = '37.5rem'; // alias/size/footer/col-width-sitemap (600px)
const COLOUR_HALF_INV = 'rgba(255, 255, 255, 0.5)'; // alias/color/opacity-50-inverse
const SIZE_MODAL_SUB = '30rem'; // alias/size/modal/footer (480px)
const SIZE_SUB_BODY_MAX = '12.5rem'; // alias/size/footer/subscribe-body-max (200px)
// Reserved height for the subscribe control slot, so swapping the field for the result message
// cannot re-flow the footer. 2.8125rem = 45px, the height ZimmInputAction currently renders
// (36px content + 4px/4px padding + 1px border). PROVISIONAL: Figma's success state keeps a
// Textfield instance at 320x59 (node 4019:46044 > Stay In Touch Section), so the designed slot
// is 59px in both states — there is no token for it and actionSizes.height offers only 52/40.
// Pending Kiera. rem, not px: the slot holds text and must grow with root font-size (WCAG 1.4.4).
const SIZE_SUBSCRIBE_SLOT = '2.8125rem';

// footer.ts owns:
//   • Non-responsive colour tokens (container, bottomBar)
//   • All responsive layout styles for each named part — consumed via __css in footer/index.tsx
//   • localeButton typography (textStyle token) + interactive states (_focusVisible)
//
// FooterStyles <style> tag is removed; no className-based CSS or !important guards remain.
// Chakra controls injection order via Emotion, so specificity is predictable.
export const ZimmFooter = {
  parts: [
    'container',
    'main',
    'contentRow',
    'subscribe',
    'subscribeHeading',
    'subscribeBody',
    'subscribeControl',
    'subscribeSuccess',
    'subscribeModalPanel',
    'modalOverlay',
    'modalTitle',
    'modalField',
    'modalFieldLast',
    'modalConsent',
    'modalConsentLink',
    'modalDisclaimer',
    'modalActions',
    'links',
    'linksInner',
    'linkCol',
    'logo',
    'columnHeading',
    'linkList',
    'linkListItem',
    'contactRow',
    'contactIconLink',
    'logoButton',
    'copyright',
    'legalLink',
    'bottomBar',
    'bottomInner',
    'bottomRight',
    'legalGrid',
    'localeText',
    'localeButton',
  ],
  baseStyle: {
    // ─── Root container ────────────────────────────────────────────────
    container: {
      backgroundColor: 'background.05',
      width: '100%',
    },

    // ─── Main layout ───────────────────────────────────────────────────
    // Figma: Content area and Logo area are siblings inside the dark footer.
    main: {
      display: 'flex',
      flexDirection: 'column',
    },

    // Figma mobile Content (node 40000407-22493): px-[32px] py-[48px]
    // Figma tablet/desktop Content (node 40000407-23484): pt-[64px] pb-[48px] px-[40px]
    contentRow: {
      display: 'flex',
      flexDirection: 'column',
      gap: SPACE_SECTION,
      padding: `${SPACE_SECTION} var(--zimm-scale-2xl)`,
      [`@media (min-width: ${BP.tablet})`]: {
        flexDirection: 'row',
        justifyContent: 'space-between',
        gap: 0,
        padding: `var(--zimm-scale-4xl) var(--zimm-scale-3xl) ${SPACE_SECTION}`,
      },
    },

    // Subscribe column — capped at 320px at every breakpoint
    subscribe: {
      maxWidth: SIZE_COL_SUB,
      [`@media (min-width: ${BP.tablet})`]: {
        flex: `0 0 ${SIZE_COL_SUB}`,
        maxWidth: 'none',
      },
    },

    // Subscribe heading — Figma node 40000461:10415 binds brand/font/lineHeight/450 (18px).
    // Unlike nav column headings (unbound 100%), this heading has a bound token.
    subscribeHeading: {
      textStyle: 'navigation',
      // Figma: brand/font/family/body (node 40000538:24875) — deliberate override of
      // textStyles.navigation's heading family.
      fontFamily: 'var(--zimm-font-family-body)',
      margin: 0,
      color: 'var(--zimm-color-text-inverse-grey)',
      lineHeight: 'var(--zimm-font-lineheight-2xs)',
      marginBottom: 'xl',
    },

    // Subscribe body paragraph — caption: 12px / 500 / 18px / no uppercase.
    subscribeBody: {
      textStyle: 'caption',
      fontFamily: 'var(--zimm-font-family-body)', // Figma node 40000538:24875
      margin: 0,
      color: 'var(--zimm-color-text-inverse)',
      maxWidth: SIZE_SUB_BODY_MAX,
      marginBottom: '3xl',
    },

    // Subscribe post-submit confirmation — body2: 14px / 400 / 18px.
    // Figma footer/textfield "Subscribed=True": container has py-16px (alias/space/400).
    // Reserves the control slot. minHeight rather than height so copy that genuinely needs a
    // third line on a narrow viewport still grows instead of clipping; centring only positions
    // the content, it does not define the height — the message keeps its own textStyle leading.
    subscribeControl: {
      minHeight: SIZE_SUBSCRIBE_SLOT,
      display: 'flex',
      flexDirection: 'column',
      justifyContent: 'center',
    },
    subscribeSuccess: {
      textStyle: 'body2',
      margin: 0,
      color: 'var(--zimm-color-text-inverse)',
    },

    // ─── Subscribe modal (HPC-035 / HPC-037) ───────────────────────────
    // Rendered through a portal, so it escapes the footer stacking context.
    modalOverlay: {
      position: 'fixed',
      inset: 0,
      // brand dark overlay (grey-900 base), not pure black
      background: 'var(--zimm-color-opacity-50)',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      padding: 'l',
      // Chakra zIndices.overlay (1300). Must clear the sticky header, which sets
      // zIndex: 'sticky' (1100) in header.ts. The portal target is document.body, so
      // this competes in the root stacking context, not the footer's.
      zIndex: 'overlay',
    },
    modalTitle: {
      textStyle: 'heading3',
      margin: 0,
      marginBottom: '3xl',
      color: 'var(--zimm-color-text-default)',
    },
    modalField: { marginBottom: 'xl' },
    modalFieldLast: { marginBottom: '3xl' },
    // Caption-weight consent/disclaimer copy — text.secondary (#666, 5.74:1 on white).
    // text.muted (#969696) would fail WCAG AA 4.5:1 at 12px on the white modal panel.
    modalConsent: {
      textStyle: 'caption',
      margin: 0,
      marginBottom: 'm',
      color: 'var(--zimm-color-text-secondary)',
    },
    modalConsentLink: {
      color: 'var(--zimm-color-text-secondary)',
      textDecoration: 'underline',
    },
    modalDisclaimer: {
      textStyle: 'caption',
      margin: 0,
      marginBottom: '3xl',
      color: 'var(--zimm-color-text-secondary)',
    },
    modalActions: { display: 'flex', gap: 'm', justifyContent: 'flex-end' },

    // Subscribe modal panel — light surface contrasting the dark footer.
    subscribeModalPanel: {
      backgroundColor: 'var(--zimm-color-bg-07)',
      width: '100%',
      maxWidth: SIZE_MODAL_SUB,
      padding: '3xl',
    },

    // Site-map column — fills remaining space at tablet, fixed 600px at desktop
    links: {
      [`@media (min-width: ${BP.tablet})`]: {
        flex: 1,
      },
      [`@media (min-width: ${BP.desktop})`]: {
        flex: `0 0 ${SIZE_COL_MAP}`,
      },
    },

    // Figma: flex-wrap on mobile (2-col), nowrap on tablet, justify-between on desktop
    linksInner: {
      display: 'flex',
      flexWrap: 'wrap',
      gap: 'var(--zimm-scale-3xl)',
      alignContent: 'flex-start',
      alignItems: 'flex-start',
      [`@media (min-width: ${BP.tablet})`]: {
        flexWrap: 'nowrap',
        gap: 'var(--zimm-scale-3xl)',
        justifyContent: 'flex-end',
      },
      [`@media (min-width: ${BP.tabletWide})`]: {
        gap: 'var(--zimm-scale-5xl)',
      },
      [`@media (min-width: ${BP.desktop})`]: {
        gap: 0,
        justifyContent: 'space-between',
      },
    },

    // Figma: flex-col, gap-16px, 140px wide on mobile; content-sized on tablet+ but CAPPED.
    //
    // The cap reproduces a per-item constraint in the design. Figma's "ACKNOWLEDGEMENT OF
    // COUNTRY" item (40000407:11004) is 118x38 — its 118px is the box AFTER wrapping (the
    // width of the word "ACKNOWLEDGEMENT"), not its natural width, which is ~188px. Every
    // other nav label is narrower and stays on one line, including "BOOK AN APPOINTMENT"
    // at 135x24. So the design's implicit threshold sits between 135 and 188.
    //
    // 160px (--zimm-scale-7xl) is inside that window under BOTH fonts, which matters because
    // the fallback stack renders ~13% wider than Futura Round (unlicensed for web — see
    // frozenFiles.md). Measured natural widths, fallback / Futura:
    //   ACKNOWLEDGEMENT OF COUNTRY  212 / ~188  -> wraps under both            (> 160)
    //   "ACKNOWLEDGEMENT" alone     130 / ~115  -> break lands after it        (< 160)
    //   BOOK AN APPOINTMENT         149 / ~135  -> stays on one line under both (< 160)
    // A 140px cap (SIZE_COL_NAV) was tried first and wrongly wrapped BOOK AN APPOINTMENT.
    //
    // Exact column widths still will not match Figma (Help 120 vs 106) — those are
    // content-driven and follow the font. Not a build defect.
    // Pending Kiera: confirm a column cap is the right rule vs a per-item wrap.
    linkCol: {
      display: 'flex',
      flexDirection: 'column',
      gap: 'm',
      alignItems: 'flex-start',
      width: SIZE_COL_NAV,
      minWidth: 0,
      flexShrink: 0,
      [`@media (min-width: ${BP.tablet})`]: {
        width: 'auto',
        maxWidth: 'var(--zimm-scale-7xl)', // 10rem (160px) — see the threshold note above
        flexShrink: 1,
      },
    },

    // Figma Logo area: px-[32px] py-[48px] on mobile, px-[40px] at tablet/desktop.
    //
    // The mobile divider above the logo is INSET, not full-bleed. Figma models it as its own
    // Container frame (40000407:23093) holding a Divider vector at x=20 w=362 inside a 402px
    // frame — i.e. 20px clear on each side, bound to alias/space/500 (= spacing.l = 20px).
    // A border-top cannot express that (it always spans the element), so it is drawn as an
    // inset pseudo-element instead. Mobile only: neither the tablet (40000407:23483) nor the
    // desktop (1892:50509) frame contains a Divider node.
    //
    // Colour is still COLOUR_HALF_INV (50% white) pending a visual check — Figma binds
    // alias/color/field/border/inverse/default (#ffffff) on the vector, but the variable list
    // does not expose layer opacity, so an opaque stroke at 50% layer opacity would look
    // identical. See the provisional-token audit (D1-6).
    logo: {
      padding: `${SPACE_SECTION} var(--zimm-scale-2xl)`,
      display: 'flex',
      flexDirection: 'column',
      justifyContent: 'center',
      alignItems: 'flex-start',
      position: 'relative',
      _before: {
        content: '""',
        position: 'absolute',
        top: 0,
        left: 'var(--zimm-scale-l)',
        right: 'var(--zimm-scale-l)',
        height: 'var(--zimm-border-width-default)',
        background: COLOUR_HALF_INV,
      },
      [`@media (min-width: ${BP.tablet})`]: {
        _before: { display: 'none' },
        paddingLeft: 'var(--zimm-scale-3xl)',
        paddingRight: 'var(--zimm-scale-3xl)',
      },
    },
    // Wordmark button — a reset, not a look. The logo owns its own geometry, so this only
    // strips the button chrome and supplies the focus ring the anchor-less markup would
    // otherwise lack (WCAG 2.4.7). Matches the contact icons' ring.
    logoButton: {
      display: 'block',
      background: 'none',
      border: 'none',
      padding: 0,
      cursor: 'pointer',
      _focusVisible: {
        outline: 'var(--zimm-border-width-default) solid',
        outlineColor: 'text.inverse',
        outlineOffset: 'var(--zimm-focus-ring-offset-default)',
      },
    },

    // ─── Link columns ──────────────────────────────────────────────────
    // Nav column headings (About / Contact / Help) — Figma "Default/Navigation".
    // fontFamily overrides the heading family textStyles.navigation carries:
    // Figma binds brand/font/family/body here (node 40000407:11736).
    columnHeading: {
      textStyle: 'navigation',
      fontFamily: 'var(--zimm-font-family-body)',
      margin: 0,
      color: 'var(--zimm-color-text-inverse-grey)', // alias/color/text/inverse/subtle
    },
    // Figma Links div: flex-col, items-start, width 100%.
    linkList: {
      listStyle: 'none',
      padding: 0,
      margin: 0,
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'flex-start',
      width: '100%',
      gap: 0,
    },
    // display:flex, not the default list-item. ZimmNavItem renders an inline-flex <a> of
    // exactly 24px, but a block-level <li> wraps it in a line box whose 24px strut adds
    // descender space below the baseline — measured 25.5px against the anchor's 24px. That
    // 1.5px leaked once per row (and 3px on the wrapped "Acknowledgement of Country"),
    // making the links column 9px taller than Figma's 158px. Making the <li> a flex
    // container removes the line box entirely, so its height is just the anchor's.
    linkListItem: { listStyle: 'none', display: 'flex' },
    contactRow: {
      display: 'flex',
      gap: '2xs',
      alignItems: 'center',
      paddingTop: '2xs',
    },
    // Contact icon touch target — 24px, matches Figma 24x24 (WCAG 2.2 SC 2.5.8).
    // MUST be the CSS var, not the bare token key 'xl': Chakra resolves width/height
    // through theme.sizes, not theme.space, and Chakra's default sizes.xl is 36rem
    // (576px) — which blew each icon up to 576px and destroyed the whole footer layout.
    // foundation/sizes.ts documents why the Zimmermann scale is deliberately not
    // registered as theme.sizes. Same rule applies to boxSize/min/maxWidth/Height.
    contactIconLink: {
      display: 'inline-flex',
      alignItems: 'center',
      justifyContent: 'center',
      width: 'var(--zimm-scale-xl)',
      height: 'var(--zimm-scale-xl)',
      // ZimmIcon defaults to currentColor — the glyph inherits this.
      color: 'var(--zimm-color-text-inverse)',
      // Focus ring: these render as anchors once Contentful supplies hrefs, so they are
      // keyboard-reachable and need a visible indicator (WCAG 2.4.7). Mirrors localeButton.
      _focusVisible: {
        outline: 'var(--zimm-border-width-default) solid',
        outlineColor: 'text.inverse',
        outlineOffset: 'var(--zimm-focus-ring-offset-default)',
      },
    },

    // Copyright + legal links share the footer text style; py-8px matches Figma Small/Default.
    copyright: {
      textStyle: 'footer',
      color: 'var(--zimm-color-text-muted)',
      whiteSpace: 'nowrap',
      paddingY: 'xs',
      paddingX: 0,
    },
    legalLink: {
      textStyle: 'footer',
      color: 'var(--zimm-color-text-muted)',
      justifyContent: 'flex-start',
      // No height override — ZimmNavItem's baseStyle uses minHeight, so the py-8px
      // below grows the item naturally. Figma Small/Default: py-[8px].
      paddingY: 'xs',
      paddingX: 0,
    },

    // ─── Bottom bar ────────────────────────────────────────────────────
    bottomBar: {
      backgroundColor: 'background.06',
      width: '100%',
    },

    // Figma: stacked column on mobile, single row on tablet+
    bottomInner: {
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'flex-start',
      gap: 0,
      padding: 'var(--zimm-scale-xl) var(--zimm-scale-2xl)',
      [`@media (min-width: ${BP.tablet})`]: {
        flexDirection: 'row',
        alignItems: 'center',
        justifyContent: 'space-between',
        // Gutter widens here, not at BP.desktop. contentRow and logo both step from 2xl to
        // 3xl at BP.tablet, so holding this at 2xl until 1024px left the whole 768-1023px
        // band with the bottom bar inset 8px less than the content above it — the locale
        // control and the legal links sat left of the subscribe column and the logo.
        padding: 'var(--zimm-scale-xl) var(--zimm-scale-3xl)',
      },
    },

    // Right group: copyright span + legalGrid div stacked on mobile, flex-row on tablet.
    // copyright is a direct flex child (no wrapper div) to match Figma's flat Legal row.
    bottomRight: {
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'flex-start',
      gap: 'var(--zimm-scale-xs)',
      width: '100%',
      [`@media (min-width: ${BP.tablet})`]: {
        flexDirection: 'row',
        alignItems: 'center',
        justifyContent: 'flex-end',
        gap: `0 var(--zimm-scale-xl)`,
        width: 'auto',
      },
      [`@media (min-width: ${BP.desktop})`]: {
        gap: `0 var(--zimm-scale-2xl)`,
      },
    },

    // Legal links: 2-col flex-wrap grid on mobile; inline flex row inside bottomRight at tablet+.
    // Avoids display:contents (unreliable in Emotion __css media queries) — legalGrid stays a
    // normal flex container but switches from a full-width wrap to an auto-width nowrap row.
    legalGrid: {
      display: 'flex',
      flexWrap: 'wrap',
      alignContent: 'flex-start',
      gap: `0 var(--zimm-scale-3xl)`,
      width: '100%',
      '& > a': { width: SIZE_COL_NAV },
      [`@media (min-width: ${BP.tablet})`]: {
        flexWrap: 'nowrap',
        gap: `0 var(--zimm-scale-xl)`,
        width: 'auto',
        '& > a': { width: 'auto' },
      },
      [`@media (min-width: ${BP.desktop})`]: {
        gap: `0 var(--zimm-scale-2xl)`,
      },
    },

    // Locale button inner text span — py-8px at EVERY breakpoint. Figma's Language item is
    // h=23 (8px + 7px text + 8px) identically on desktop (40000407:14372) and mobile
    // (40000407:23934), and its Legal row opposite is also h=23, so both ends of the bottom
    // bar share a height. A previous tablet+ `padding: 0` override collapsed this to 14px
    // against the 31px legal links — removed.
    localeText: {
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      paddingY: 'xs',
      paddingX: 0,
      whiteSpace: 'nowrap',
    },

    // ─── Locale button ─────────────────────────────────────────────────
    // textStyle: 'footer' consolidates: FONT_MEDIUM / 10px / 500 / 14px / 0.4px / uppercase
    localeButton: {
      textStyle: 'footer',
      color: 'text.inverse',
      display: 'inline-flex',
      alignItems: 'center',
      gap: '2xs',
      background: 'none',
      border: 'none',
      padding: 0,
      cursor: 'pointer',
      whiteSpace: 'nowrap',
      _focusVisible: {
        outline: 'var(--zimm-border-width-default) solid',
        outlineColor: 'text.inverse',
        outlineOffset: 'var(--zimm-focus-ring-offset-default)',
      },
    },
  },
};

