import React from 'react';
import type { Meta, StoryObj } from '@storybook/react';
import { expect, userEvent, within } from 'storybook/test';
import { Footer } from './index';
import { FOOTER_FIXTURE } from './contentfulFixture';

const meta: Meta<typeof Footer> = {
  title: 'Layout/Footer',
  component: Footer,
  parameters: {
    layout: 'fullscreen',
  },
  args: {
    data: FOOTER_FIXTURE,
  },
};

export default meta;
type Story = StoryObj<typeof Footer>;

export const Default: Story = {
  render: (args) => (
    <div style={{ width: '100%' }}>
      <Footer {...args} />
    </div>
  ),
  // Asserts leavesTheSite's scheme branch. Security-adjacent: rel="noopener noreferrer" is what
  // stops the storefront URL reaching WhatsApp in the Referer header, and the accessible-name
  // suffix is WCAG 3.2.5. Nothing else in CI covered this — the behaviour was only ever verified
  // by hand, which is exactly the kind of gap that survives a refactor invisibly.
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);

    // http(s) → new tab, hardened, and the name says so
    const whatsApp = canvas.getByRole('link', { name: /whatsapp/i });
    await expect(whatsApp).toHaveAttribute('target', '_blank');
    await expect(whatsApp).toHaveAttribute('rel', 'noopener noreferrer');
    await expect(whatsApp).toHaveAccessibleName(/opens in a new tab/i);

    // tel:/mailto: hand off to the OS — a target would do nothing, so there must not be one
=== stories 150,260 ===
  ),
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);

    // Absent and unsafe both render the icon as a labelled span: no href, no tab stop, so
    // nothing promises an action that cannot be performed (WCAG 2.4.4 / 3.2.4) — but the
    // channel stays perceivable rather than silently disappearing.
    for (const name of [/call us/i, /whatsapp/i]) {
      await expect(canvas.queryByRole('link', { name })).not.toBeInTheDocument();
      await expect(canvas.getByRole('img', { name })).toBeInTheDocument();
    }

    // The safe channel is unaffected — degradation is per-channel, not all-or-nothing.
    await expect(canvas.getByRole('link', { name: /email us/i })).toHaveAttribute('href', 'mailto:care@zimmermann.com');
  },
};

/**
 * The path SFCC-55 actually ships. Its AC scopes the Stay in Touch section to "an email input
 * field and submit button as a placeholder component" and defers the Omneo sign-up, so a valid
 * email resolves straight to the placeholder message with no name-capture modal.
 */
export const SubscribePlaceholder: Story = {
  name: 'Subscribe — placeholder path (SFCC-55 default)',
  render: (args) => (
    <div style={{ width: '100%' }}>
      <Footer {...args} />
    </div>
  ),
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    const footer = canvasElement.querySelector('footer[role="contentinfo"]') as HTMLElement;
    const slot = footer.querySelector('[aria-live]') as HTMLElement;
    const heightBefore = footer.getBoundingClientRect().height;
    const slotBefore = slot.getBoundingClientRect().height;

    await userEvent.type(canvas.getByRole('textbox', { name: /email/i }), 'test@example.com');
    await userEvent.click(canvas.getByRole('button', { name: /subscribe/i }));

    // No modal — the default build does not collect names (HPC-035 is a separate story with no
    // design yet). Queried against document.body because the modal would portal outside canvas.
    await expect(within(document.body).queryByRole('dialog')).not.toBeInTheDocument();

    // The shopper still gets honest feedback rather than a false success.
    await expect(canvas.getByText(/temporarily unavailable/i)).toBeInTheDocument();
    await expect(canvas.queryByText(/on the list/i)).not.toBeInTheDocument();

    // No layout shift. The field and the message are different heights (45px vs 36px of text),
    // so without subscribeControl's minHeight reservation the column re-flows — measurably at
    // every viewport, and visibly on mobile where the columns stack and the footer itself moves.
    // Asserted on the slot as well as the footer: at desktop widths the taller site-map column
    // sets the row height, so a footer-only check passes even when the column has shifted.
    const rounded = (n: number) => Math.round(n * 10) / 10;
    await expect(rounded(slot.getBoundingClientRect().height)).toBe(rounded(slotBefore));
    await expect(rounded(footer.getBoundingClientRect().height)).toBe(rounded(heightBefore));
  },
};

