import React, { useState, useRef } from 'react';
import { createPortal } from 'react-dom';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { ZimmLogo } from 'app/components/ui-kits/atoms/zimmLogo';
import { ZimmIcon } from 'app/components/ui-kits/atoms/zimmIcon';
import { ZimmNavItem } from 'app/components/ui-kits/atoms/zimmNavItem';
import { ZimmButton } from 'app/components/ui-kits/atoms/zimmButton';
import { ZimmTextInput } from 'app/components/ui-kits/atoms/zimmTextInput';
import { ZimmInputAction } from 'app/components/ui-kits/molecules/zimmInputAction';
import { isSafeHref } from 'app/utils/safeHref';
import { useSubscribeModal } from 'app/hooks/useSubscribeModal';
import { noop } from '@salesforce/retail-react-app/app/utils/utils';
import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
import { useHistory } from 'react-router-dom';
import { HOME_HREF } from '@salesforce/retail-react-app/app/constants';
import type { FooterConfigEntry } from 'app/types/contentful';
import { FOOTER_FIXTURE } from './contentfulFixture';

// Named constant to avoid magic string comparison in the render tree
/** Non-breaking space. Marks a label whose line break is intentional — see the nav item below. */
const NBSP = '\u00A0';

/**
 * Theme recipe key. Namespaced rather than 'Footer' because extendTheme deep-merges — a recipe
 * named Footer would inherit base SFCC's Footer instead of replacing it. Must match the key
 * registered in theme/components/index.ts; a typo here silently yields an empty style object.
 */
const ZIMM_FOOTER_RECIPE = 'ZimmFooter';
// Locale control label. Hardcoded, and deliberately NOT fixture data — region and currency
// come from site config (config/default.js: defaultSite 'ZimmermannAU'), not Contentful, so
// FooterConfigEntry has no field for them. Set to match the site the app actually serves at
// '/'; it previously read "United States (USD) / ENG" on an AU storefront. The real fix reads
// site.l10n.defaultLocale and the site's currency via useMultiSite when the locale selector
// lands, at which point this constant goes away rather than getting a different literal.
const LOCALE_LABEL_PLACEHOLDER = 'Australia (AUD) / ENG';

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------
type FooterProps = {
  /** Contentful FooterConfigEntry. Pass FOOTER_FIXTURE from contentfulFixture.ts in stories/tests. */
  data: FooterConfigEntry;
  copyrightYear?: number;
  /** Forces SubscribeSection into its post-submit state. For Storybook/tests only. */
  initialSubscribed?: boolean;
  /**
   * Opt in to the HPC-035 first/last-name capture modal. Defaults to false: SFCC-55 ships the
   * Stay in Touch section as an input plus submit button only, and the modal has no design yet.
   */
  enableNameCapture?: boolean;
  /** Click handler for the wordmark. Mirrors the header's onLogoClick prop, defaulting to
   *  noop so the presentational Footer never navigates on its own. */
  onLogoClick?: () => void;
  /** href for the Privacy Policy link inside the subscribe modal (HPC-037). Locale-aware at runtime. */
  privacyPolicyHref?: string;
};

// ---------------------------------------------------------------------------
// All footer styling lives in theme/components/footer.ts and is consumed via
// useMultiStyleConfig('ZimmFooter') → __css. Nothing is styled at the call site.

