import { chromium } from '/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/node_modules/playwright-core/index.js';

const measure = async (page, width) => {
  await page.setViewportSize({ width, height: 900 });
  await page.waitForTimeout(400);
  return await page.evaluate(() => {
    const out = {};
    const footer = document.querySelector('footer[role="contentinfo"]');
    if (!footer) return { error: 'no footer' };
    // nav columns: linkCol divs
    const cols = [...footer.querySelectorAll('ul')].map((ul) => {
      const col = ul.parentElement;
      const heading = col.querySelector('p');
      const lis = [...ul.querySelectorAll(':scope > li')];
      return {
        heading: heading?.textContent?.trim(),
        headingPL: heading ? getComputedStyle(heading).paddingLeft : null,
        items: lis.map((li) => {
          const a = li.querySelector('a, span[role], div');
          const navItem = li.querySelector('a');
          const r = li.getBoundingClientRect();
          const nr = navItem ? navItem.getBoundingClientRect() : null;
          return {
            text: (li.textContent || '').trim().slice(0, 34),
            liPL: getComputedStyle(li).paddingLeft,
            liW: Math.round(r.width * 100) / 100,
            liH: Math.round(r.height * 100) / 100,
            navW: nr ? Math.round(nr.width * 100) / 100 : null,
            navH: nr ? Math.round(nr.height * 100) / 100 : null,
            liWidthProp: getComputedStyle(li).width,
            navInlineWidth: navItem ? getComputedStyle(navItem).width : null,
            hasIconRow: !!li.querySelector('svg') && !navItem,
          };
        }),
      };
    });
    out.cols = cols;
    out.footerH = Math.round(footer.getBoundingClientRect().height * 100) / 100;
    return out;
  });
};

