/**
 * useSubscribeModal — the two branches no footer story can reach.
 *
 * The footer's `SubscribeModalOpen` story already covers mount, focus-into-first-field, the Tab
 * trap in both wrap directions, the body-scroll lock and Escape-with-focus-restore against the
 * real SubscribeModal markup, so none of that is repeated here (testing.md: pick the cheapest
 * layer that proves the behaviour, once). Two things it structurally cannot prove:
 *
 *   1. The trap's `!el.hasAttribute('disabled')` filter. Nothing in SubscribeModal is ever
 *      disabled, so from a footer story the filter has nothing to exclude and removing it
 *      changes no observable behaviour. It needs a synthetic control at each end of the focus
 *      order — a disabled element that WOULD be picked as `first`/`last` if it were not filtered
 *      out. Without the filter the trap would hand focus to a control the browser will not
 *      accept it on, i.e. it would silently stop trapping (WCAG 2.1.2).
 *   2. The scroll lock restoring a NON-EMPTY previous value. A story can only ever observe the
 *      default '' being put back, which is indistinguishable from the effect clearing the
 *      property outright.
 *
 * `.tsx` rather than `.ts` because a hook this stateful is only meaningfully exercised through a
 * mounted component (components.md puts hooks in `.ts`; that rule is about hook *sources*).
 */
import React from 'react';
import { afterEach, describe, expect, test } from 'vitest';
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { useSubscribeModal } from './useSubscribeModal';

const FIRST_ENABLED_LABEL = 'Email';
const LAST_ENABLED_LABEL = 'Continue';
/** Inline value on <body> before the lock engages, so the restore has something to get wrong. */
const PRE_EXISTING_OVERFLOW = 'scroll';

type TrapHarnessProps = {
  isOpen: boolean;
  onClose?: () => void;
};

/**
 * Stand-in for SubscribeModal: a form the hook can bound its trap to, wrapping a disabled
 * control at BOTH ends of the focus order. Unfiltered, `first` would resolve to "Disabled
 * leading" and `last` to "Disabled trailing", and neither wrap below would ever fire. The
 * "Outside" button gives focus somewhere real to escape to when the trap is broken, so a
 * failure reads as "focus left the form" rather than "focus landed on <body>".
 */
const TrapHarness = ({ isOpen, onClose = () => undefined }: TrapHarnessProps) => {
  const { formRef, firstFocusRef } = useSubscribeModal({ isOpen, onClose });
  return (
    <>
      <button type="button">Outside</button>
      {isOpen && (
        <form ref={formRef}>
          <button type="button" disabled>
            Disabled leading
          </button>
          <div ref={firstFocusRef}>
            <input aria-label={FIRST_ENABLED_LABEL} />
          </div>
          <button type="button">{LAST_ENABLED_LABEL}</button>
          <button type="button" disabled>
            Disabled trailing
          </button>
        </form>
      )}
    </>
  );
};

/**
 * Opens the harness and waits out the hook's deferred focus-into-first-field before handing
 * back. Without the wait, that setTimeout(0) would fire during the first `await` below and
 * steal focus back from whatever the test had just focused.
 */
const renderOpen = async () => {
  const user = userEvent.setup();
  render(<TrapHarness isOpen />);
  const first = screen.getByLabelText(FIRST_ENABLED_LABEL);
  await waitFor(() => expect(first).toHaveFocus());
  return { user, first, last: screen.getByRole('button', { name: LAST_ENABLED_LABEL }) };
};

afterEach(() => {
  document.body.style.overflow = '';
});

describe('useSubscribeModal — the Tab trap skips disabled controls', () => {
  test('forward Tab from the last enabled control wraps to the first', async () => {
    const { user, first, last } = await renderOpen();

    // Focused, not clicked: the real modal's last control is a submit button.
    last.focus();
    expect(last).toHaveFocus();

    await user.tab();

    // Only reachable if `last` resolved to the enabled control rather than the disabled one
    // trailing it — otherwise the trap never fires and focus leaves the form entirely.
    expect(first).toHaveFocus();
  });

  test('Shift+Tab from the first enabled control wraps to the last', async () => {
    const { user, first, last } = await renderOpen();
    expect(first).toHaveFocus();

    await user.tab({ shift: true });

    expect(last).toHaveFocus();
  });
});

describe('useSubscribeModal — body-scroll lock', () => {
  test('restores the inline overflow it found rather than clearing the property', () => {
    document.body.style.overflow = PRE_EXISTING_OVERFLOW;

    const { rerender } = render(<TrapHarness isOpen={false} />);
    expect(document.body.style.overflow).toBe(PRE_EXISTING_OVERFLOW);

    rerender(<TrapHarness isOpen />);
    expect(document.body.style.overflow).toBe('hidden');

    rerender(<TrapHarness isOpen={false} />);
    expect(document.body.style.overflow).toBe(PRE_EXISTING_OVERFLOW);
  });
});
